import { expect, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

const cases = [
  {
    label: "an empty file",
    kind: "w9",
    status: 422,
    code: "empty_file",
    file: { name: "empty.pdf", mimeType: "application/pdf", buffer: Buffer.alloc(0) },
  },
  {
    label: "a file of exactly 10 MiB + 1",
    kind: "w9",
    status: 413,
    code: "file_too_large",
    file: {
      name: "huge.pdf",
      mimeType: "application/pdf",
      buffer: Buffer.alloc(TEN_MIB + 1, 0x41),
    },
  },
  {
    label: 'a ".exe" file',
    kind: "w9",
    status: 415,
    code: "unsupported_type",
    file: {
      name: "setup.exe",
      mimeType: "application/x-msdownload",
      buffer: Buffer.from("MZ\x90\x00 fake executable"),
    },
  },
  {
    label: "a valid text file",
    kind: "passport",
    status: 422,
    code: "validation_error",
    file: { name: "notes.txt", mimeType: "text/plain", buffer: Buffer.from("hello world") },
  },
] as const;

test.describe("Upload vendor documents - reject invalid uploads", () => {
  for (const c of cases) {
    test(
      `rejects ${c.label} as kind "${c.kind}" with ${c.status} ${c.code}`,
      { tag: "@DOC-04" },
      async ({ apiAs }) => {
        // Arrange: a vendor in status "draft" owned by the member's tenant
        const member = await apiAs("member");
        const vendorResponse = await member.post("/api/vendors", {
          data: {
            name: uniqueName("DOC-04 Vendor"),
            category: "services",
            contact_email: `ops-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@vendor.test`,
          },
        });
        expect(vendorResponse.status()).toBe(201);
        const vendor = await vendorResponse.json();
        expect(vendor.status).toBe("draft");

        // Act
        const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind: c.kind,
            file: c.file,
          },
        });

        // Assert
        expect(response.status()).toBe(c.status);
        const body = await response.json();
        expect(body.error?.code).toBe(c.code);
      },
    );
  }
});
